    private static final Map<Integer, String> MAPPING = parse();

    private static Map<Integer, String> parse() {
        String all = String.join(",", TABLE);
        Map<Integer, String> mapping = new HashMap<>(8192);
        for (String entry : all.split(",")) {
            int arrow = entry.indexOf('>');
            StringBuilder target = new StringBuilder();
            for (String cp : entry.substring(arrow + 1).split(" ")) {
                target.appendCodePoint(Integer.parseInt(cp, 16));
            }
            mapping.put(Integer.parseInt(entry.substring(0, arrow), 16), target.toString());
        }
        return Map.copyOf(mapping);
    }

    /**
     * {@code skeleton(text)} per UTS #39 §4. Two names are confusable exactly when this returns equal
     * strings for them; the value itself is not meaningful and is never shown to an author.
     */
    public static String skeleton(String text) {
        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
        StringBuilder mapped = new StringBuilder(decomposed.length());
        decomposed.codePoints().forEach(cp -> {
            String replacement = MAPPING.get(cp);
            if (replacement == null) {
                mapped.appendCodePoint(cp);
            } else {
                mapped.append(replacement);
            }
        });
        return Normalizer.normalize(mapped, Normalizer.Form.NFD);
    }
